        || (!other.atoms.is_empty() && !self.radicals.is_empty())
    {
        return None;
    }
    if let ([(left, left_coefficient)], [(right, right_coefficient)]) =
        (self.radicals.as_slice(), other.radicals.as_slice())
        && left == right
        && !left.is_one()
    {
        // The opaque-product guard above proves that both atom vectors
        // are empty. Keep the original arithmetic and insertion order.
        let rational = &self.rational * &other.rational;
        let mut linear = left_coefficient * &other.rational;
        let right_linear = right_coefficient * &self.rational;
        let take_right = linear.sign() == Sign::NoSign;
        if take_right {
            linear = right_linear;
        } else if right_linear.sign() != Sign::NoSign {
            linear = linear + right_linear;
        }
        let cross = left_coefficient * right_coefficient;
        let rational = rational + cross * left;
        if linear.sign() == Sign::NoSign {
            return Some(Self::rational(rational));
        }
        if take_right {
            // Ordinary insertion selects the first surviving payload,
            // including distinct equal-valued right radicand storage.
            self.radicals[0].0 = right.clone();
